def get_units_for_grade(grade: int) -> list[IngUnit]:
    return list(ING_CURRICULUM.get(grade, []))


def get_unit(grade: int, unit_id: str) -> IngUnit | None:
    for u in ING_CURRICULUM.get(grade, []):
        if u["unit_id"] == unit_id:
            return u
    return None


def get_unit_kazanim(grade: int, unit_id: str, kazanim_kod: str) -> IngKazanim | None:
    unit = get_unit(grade, unit_id)
    if unit is None:
        return None
    for k in unit["kazanimlar"]:
        if k["kod"] == kazanim_kod:
            return k
    return None


def find_unit_by_kazanim(kazanim_kod: str) -> tuple[int, IngUnit] | None:
    for grade, units in ING_CURRICULUM.items():
        for u in units:
            for k in u["kazanimlar"]:
                if k["kod"] == kazanim_kod:
                    return grade, u
    return None


def is_unit_available(grade: int, unit_id: str) -> bool:
    return get_unit(grade, unit_id) is not None
